"""BetterAgent: SimplifyAgent plus switchable additions (each a small method, off by its class constant).

0. GUARD_C_OPEN + HEALTH_ESTIMATE. In a strategic / bottleneck case C charges for the supplier's margin below
   `sustainable_margin_pct`; `total_cost` without a supplier estimate sees 0 (real P02 v17: 140k health cost, c_deal >
   c_open, score 0). The estimate here: full cost = the data package's should-cost for the part (within 1-2% of the
   arena's own fitted value on P01/P02/P03), interest rate = the buyer's. It is set through cost.HEALTH for the whole
   decision, so price choice, caps, closing rule and stall jump all see the health term; a sheet is never priced
   below the price that minimises estimated C; a sheet or accept above c_open gets its price raised until it fits.
1. THIRD_SHEET: a third equivalent sheet (shorter payment or another contract length, price lowered to equal C).
2. ANCHOR_BY_SHARE: first offer = max(floor, price x (1 - share x index drop)) where the case data show a drop.
3. CASH_SHORT: a cash-short supplier gets shorter payment days against a lower price.
4. LATE_ACCEPT: with <= 2 messages left, accept a standing sheet within 1% of the best known C.
5. HOLD_FOR_FINAL: no accept while the supplier's latest message is a plain "open" offer with >= HOLD_MESSAGES
   messages left, unless it repeated its price (its floor): we keep countering until it sends final_offer.
Rival-quote citation (RESEARCH rule 12) is not here: EvidenceAgent._rewrite already cites the best real rival offer ID."""

import math
import re
from contextlib import contextmanager
from contextvars import ContextVar

from ..cost import HEALTH, complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..evidence import _q, load_package
from ..guard import satisfy_must_haves
from ..play import find_sheet, latest, moves_left, standing
from . import simplify_agent
from .reciprocal import ANCHOR_FLOOR, _c_alt, _live, _mine, _pinned, _sheets, _sup
from .simplify_agent import FREE_LEVERS, SimplifyAgent, _health_at_stake

CASH_SHORT = re.compile(r"liquidity|working[- ]capital|cash[- ]?flow|short of cash|cash[- ]?(?:tight|short|constrain|crunch)", re.I)

HOLD = ContextVar("hold", default=None)  # set while BetterAgent decides: (case, threads, decision) -> True to veto a close


def _gate(real):
    """simplify's decide() starts with the closing rule; this lets BetterAgent veto it (only inside its own decide)."""
    def closing_accept(case, threads, *a, **k):
        r = real(case, threads, *a, **k)
        hold = HOLD.get()
        return None if r and hold and hold(case, threads, r) else r
    return closing_accept


simplify_agent.closing_accept = _gate(simplify_agent.closing_accept)


def _health(case):
    """{full_cost, interest_rate} of the supplier for cost.HEALTH, or None (no relationship cost / no should-cost row)."""
    if not _health_at_stake(case) or not (pkg := load_package()):
        return None
    try:
        rows = _q(pkg, "select supplier_id, unit_cost, price_unit from should_cost where part_id=?", case["parts"][0])
    except Exception:
        return None
    # the row for one of this case's suppliers, else the generic one (shortcut: a multi-supplier case uses the first match)
    row = next((r for r in sorted(rows, key=lambda r: r["supplier_id"] not in case.get("suppliers", []))), None)
    return {"full_cost": row["unit_cost"] / (row["price_unit"] or 1), "interest_rate": case["buyer"]["interest_rate"]} if row else None


@contextmanager
def _with_health(case, on=True):
    token = HEALTH.set(_health(case) if on else None)
    try:
        yield
    finally:
        HEALTH.reset(token)


class BetterAgent(SimplifyAgent):
    GUARD_C_OPEN = THIRD_SHEET = ANCHOR_BY_SHARE = CASH_SHORT_OFFER = LATE_ACCEPT = HEALTH_ESTIMATE = HOLD_FOR_FINAL = True
    LATE_MESSAGES, LATE_TOLERANCE, HOLD_MESSAGES = 2, 0.01, 3

    def decide(self, case, threads):
        token = HOLD.set(self._holds if self.HOLD_FOR_FINAL else None)
        try:
            with _with_health(case, self.HEALTH_ESTIMATE):
                if self.LATE_ACCEPT and (late := self._late_accept(case, threads)):
                    return self._guard(case, threads, late)
                return self._guard(case, threads, super().decide(case, threads))
        finally:
            HOLD.reset(token)

    # 5. hold for the final offer ----------------------------------------------------------------------------
    def _holds(self, case, threads, decision):
        """True: do not close on this thread yet (plain open offer, messages to spare, price still moving)."""
        ev = threads[decision["supplier_id"]]
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(ev) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        repeated = len(ps) >= 2 and ps[-1] == ps[-2]
        return latest(ev).get("status") == "open" and moves_left(case, ev) >= self.HOLD_MESSAGES and not repeated

    # 0. never offer or accept above c_open ------------------------------------------------------------------
    @staticmethod
    def _est_c(case, events, t, std):
        """C of a sheet, with the supplier's margin priced when the case charges for it."""
        with _with_health(case):
            return total_cost(case, t, std)

    def _open_c(self, case, threads):
        out = math.inf
        for ev in threads.values():
            std = standard_terms(ev)
            for m in _sup(ev):
                if m.get("term_sheets"):
                    for s in m["term_sheets"]:
                        t = s.get("terms") or {}
                        if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                            out = min(out, self._est_c(case, ev, t, std))
                    break
        return out

    def _repair(self, case, events, std, t, c_open, top):
        """The sheet with the lowest price >= its own at which C <= c_open (up to `top`), else None."""
        if self._est_c(case, events, t, std) <= c_open:
            return t
        lo = t["unit_price"]
        for i in range(1, 101):
            v = {**t, "unit_price": round(lo + (top - lo) * i / 100, 2)}
            if self._est_c(case, events, v, std) <= c_open:
                return v
        return None

    def _guard(self, case, threads, d):
        if not self.GUARD_C_OPEN:
            return d
        sid, msg = d.get("supplier_id"), d.get("message") or {}
        ev = threads.get(sid)
        if not ev:
            return d
        std, c_open = standard_terms(ev), self._open_c(case, threads)
        act = msg.get("action") or {}
        if act.get("type") == "accept":
            theirs = find_sheet(ev, act.get("term_sheet_id"))
            if theirs is None or self._est_c(case, ev, theirs, std) <= c_open:
                return d
            base = {k: std[k] for k in case["negotiable"] if k in std}
            sheets = [complete_offer(case, {**base, **theirs})]
        elif msg.get("term_sheets"):
            sheets = [s["terms"] for s in msg["term_sheets"]]
        else:
            return d
        first = next((m["term_sheets"][0]["terms"]["unit_price"] for m in _sup(ev) if m.get("term_sheets")), 0)
        fixed = [r for t in sheets if (r := self._repair(case, ev, std, t, c_open, max(first, t["unit_price"])))]
        if fixed == sheets:
            return d
        body = {"subject": case.get("title", "Our proposal"), "body": "Thank you for your offer. Please see our updated terms."}
        return {"supplier_id": sid, "message": {**body, "term_sheets": [{"terms": t} for t in fixed]} if fixed else
                {"subject": body["subject"], "body": "Could you please send us your best terms?"}}

    # 6. late accept ----------------------------------------------------------------------------------------
    def _late_accept(self, case, threads):
        c_alt, c_open = _c_alt(case), self._open_c(case, threads)
        known, cand = math.inf, None
        for sid in _live(threads):
            ev, std = threads[sid], standard_terms(threads[sid])
            for s in _sheets(ev):
                if (t := s.get("terms") or {}).get("unit_price") is not None and must_haves_ok(case, t, std):
                    known = min(known, self._est_c(case, ev, t, std))
            sheet_id, t = standing(ev)
            if sheet_id and moves_left(case, ev) <= self.LATE_MESSAGES and t.get("unit_price") is not None and must_haves_ok(case, t, std):
                c = self._est_c(case, ev, t, std)
                if c < c_alt and c <= c_open:
                    cand = min(cand or (c, sid, sheet_id), (c, sid, sheet_id))
        if cand and cand[0] <= (1 + self.LATE_TOLERANCE) * known:
            return {"supplier_id": cand[1], "message": {"action": {"type": "accept", "term_sheet_id": cand[2]}}}
        return None

    # 3. cost-share anchor -----------------------------------------------------------------------------------
    @staticmethod
    def _share_factor(case):
        """1 - share x drop for the best index driver the case shows falling (index_paths < 0), else None."""
        paths = case["buyer"].get("index_paths") or {}
        hits = [c["material_share"] * -paths[c["series"]] for c in (case.get("term_options") or {}).get("index_clause", [])
                if c and paths.get(c["series"], 0) < 0]
        return 1 - max(hits) if hits else None

    def _price(self, case, events, p):
        if self.ANCHOR_BY_SHARE and not _mine(events) and not _health_at_stake(case) and (f := self._share_factor(case)):
            return max(ANCHOR_FLOOR * p, min(f * p, case["buyer"].get("current_unit_price") or p))
        return super()._price(case, events, p)

    # 2 + 5. third equivalent sheet / cash-short -------------------------------------------------------------
    @staticmethod
    def _cash_short(case, events):
        text = " ".join([*(m.get("body") or "" for m in _sup(events)), str(case.get("suppliers", ""))])
        return bool(CASH_SHORT.search(text))

    def _trade_sheet(self, case, events, std, main, p, pins, seen):
        """Same C as main with another lever: shorter payment days (or another contract length) for a lower price."""
        short = self.CASH_SHORT_OFFER and self._cash_short(case, events)
        levers = ("payment_days",) if short else ("payment_days", "contract_months") if self.THIRD_SHEET else ()
        opts, best = case.get("term_options") or {}, None
        cost = lambda t: total_cost(case, t, std)  # noqa: E731
        for f in levers:
            if f not in case["negotiable"] or f in pins or (_health_at_stake(case) and f not in FREE_LEVERS):
                continue
            for o in (o for o in opts.get(f, []) if o and o != main.get(f) and (f != "payment_days" or o < main[f])):
                t = satisfy_must_haves(case, {**main, f: o}, std)
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
                if t.get(f) != o or slope <= 0:
                    continue
                price = round(min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01), 2)
                v = {**t, "unit_price": price}
                if price > 0.75 * p and v not in seen and v != main and (best is None or price > best["unit_price"]):
                    best = v
            if best:
                break
        return best

    def _sheets(self, case, events, std, theirs):
        out = super()._sheets(case, events, std, theirs)
        if out and HEALTH.get():  # never below the price that minimises C: under it the health term grows faster than the saving
            seen = [s["terms"] for m in _mine(events) for s in m.get("term_sheets") or []]
            fixed = []
            for t in out:
                grid = [round(t["unit_price"] + (theirs["unit_price"] - t["unit_price"]) * i / 100, 2) for i in range(101)]
                t = complete_offer(case, {**t, "unit_price": min(grid, key=lambda x: total_cost(case, {**t, "unit_price": x}, std))})
                if t not in fixed and t not in seen:
                    fixed.append(t)
            out = fixed
        if out and (self.THIRD_SHEET or self.CASH_SHORT_OFFER):
            seen = [s["terms"] for m in _mine(events) for s in m.get("term_sheets") or []]
            if extra := self._trade_sheet(case, events, std, out[0], theirs["unit_price"], _pinned(events), seen):
                if (extra := complete_offer(case, extra)) not in out:
                    out.append(extra)
        return out

"""Guard layer: wraps any delegate agent so a must-have is always ASKED for in the term sheet and an
open thread is never abandoned while something sensible is left to try.

Why: practice runs lost cases with no deal because sheets were snapped (by `complete_offer`) onto
an option that breaks a must-have, and the agents then walked away. `satisfy_must_haves` fixes the
sheets; `GuardedAgent` turns a delegate's walk-away (or crash) into an accept of a safe standing
sheet, or into one more counter at the supplier's own price with the must-haves satisfied.
"""

import logging

from .cost import OPS, complete_offer, must_haves_ok, snap, total_cost
from .docs import standard_terms
from .play import ENDED, closing_move, latest, live_threads, moves_left, standing

log = logging.getLogger("arena")

MAX_COUNTERS = 2  # guard counters per thread and case
EARLY_ACCEPT = 0.97  # accept a safe sheet before the last move only once the supplier has moved this far
ASK_QUOTE = "Could you please send us your quote?"
ASK_BODY = "We can proceed at your price if the terms below work for you; please confirm."


def _fits(m, value):
    try:
        return value is not None and OPS[m["op"]](value, m["value"])
    except TypeError:
        return False


def _must_have_value(case, m, current):
    """A value for the must-have's field that satisfies it, or `current` when none can."""
    op, bound = m["op"], m["value"]
    options = [o for o in (case.get("term_options") or {}).get(m["field"]) or [] if o is not None]
    if options:
        ok = [o for o in options if _fits(m, o)]
        if not ok:
            return current
        if op in ("<=", "<"):
            return max(ok)
        if op in (">=", ">"):
            return min(ok)
        if op == "!=":
            return current if _fits(m, current) else ok[0]
        return bound
    if op in ("<=", ">=", "=="):
        return bound
    if op == "!=":
        return current if _fits(m, current) else (bound + 1 if isinstance(bound, int | float) else current)
    step = 1 if isinstance(bound, int) else 0.01
    return bound - step if op == "<" else bound + step


def satisfy_must_haves(case, terms, standard=None):
    """A copy of `terms` with every must-have on a negotiable field satisfied, completed to a valid
    sheet. Must-haves on fields we cannot negotiate are left alone."""
    must = [m for m in case["buyer"].get("must_haves", []) if m["field"] in case["negotiable"]]
    result = dict(terms)
    for m in must:
        cur = result.get(m["field"])
        cur = snap(case, m["field"], cur) if cur is not None else cur  # complete_offer snaps it later
        result[m["field"]] = cur if _fits(m, cur) else _must_have_value(case, m, cur)
    result = complete_offer(case, result)
    for m in must:  # a gap filled from the plan, or a snap, may have broken it again
        if not _fits(m, result.get(m["field"])):
            result[m["field"]] = _must_have_value(case, m, result.get(m["field"]))
    if not must_haves_ok(case, result, standard):
        log.debug("guard: must-haves still fail after fixing %s", result)
    return result


def fix_sheets(case, sheets, standard=None):
    """(sheets, changes): `satisfy_must_haves` on each sheet (other keys kept); exact duplicates
    dropped; at most 3 kept. `changes`: what was changed, per input sheet, as readable text."""
    out, changes = [], []
    for s in sheets:
        old = s.get("terms") or {}
        fixed = {**s, "terms": satisfy_must_haves(case, old, standard)}
        if c := ", ".join(f"{k} {old.get(k)} -> {v}" for k, v in fixed["terms"].items() if old.get(k) != v):
            changes.append(c)
        if fixed not in out:
            out.append(fixed)
    return out[:3], changes


def _text(sid, body, sheets=None):
    msg = {"subject": "Our proposal", "body": body}
    if sheets:
        msg["term_sheets"] = sheets
    return {"supplier_id": sid, "message": msg}


def _walk(sid):
    return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}


class GuardedAgent:
    def __init__(self, delegate, log_name="arena"):
        self.delegate = delegate
        self.log = logging.getLogger(log_name)
        self._case_id = None
        self._tried = {}

    def __getattr__(self, name):  # e.g. `.chosen` of a wrapped router
        if name in ("delegate", "log", "_case_id", "_tried"):
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        """Never raises: any failure here falls back to the guard's own continuation, then closing_move."""
        if not any(threads.values()):  # nothing to look at: nothing to continue
            return _walk(next(iter(threads), None))
        try:
            return self._decide(case, threads)
        except Exception:
            log.exception("%s guard: failed", self._case_id)
        try:
            return self._keep_going(case, threads, None, "guard failed")
        except Exception:
            log.exception("%s guard: fallback failed", self._case_id)
        try:
            return closing_move(case, threads)
        except Exception:
            return _walk(next(iter(threads), None))

    def _decide(self, case, threads):
        if case.get("case_id") != self._case_id:
            self._case_id, self._tried = case.get("case_id"), {}
        error = False
        try:
            decision = self.delegate.decide(case, threads)
        except Exception:
            log.exception("%s guard: delegate crashed", self._case_id)
            decision, error = None, True
        msg = (decision or {}).get("message") or {}
        action = msg.get("action") or {}
        sid = (decision or {}).get("supplier_id")
        if decision and action.get("type") == "accept":
            if self._accept_ok(case, threads, decision):
                events = threads[sid]
                if (not any(m.get("from") == "buyer" for m in events) and moves_left(case, events) > 1
                        and not self._supplier_moved(case, threads, sid)):
                    self.log.info("%s guard: deferred round-1 accept on %s (unmoved opening offer)",
                                  self._case_id, sid)
                    return self._counter(case, threads, sid)
                return decision
            return self._keep_going(case, threads, sid, "delegate accept is not safe")
        if decision and msg.get("term_sheets"):
            sheets = self._fix(case, threads, sid, msg["term_sheets"])
            if sheets:
                return self._last_move(case, threads, {**decision, "message": {**msg, "term_sheets": sheets}})
        elif decision and not action:
            return self._last_move(case, threads, decision)  # a text-only message
        reason = (
            "delegate crashed" if error
            else "delegate wanted to walk" if action.get("type") == "walk_away"
            else f"unknown action {action.get('type')}" if action
            else "no usable sheet"
        )
        return self._keep_going(case, threads, sid, reason)

    @staticmethod
    def _accept_ok(case, threads, decision):
        """The accept names the standing sheet, keeps the must-haves and beats the alternative."""
        sid, action = decision.get("supplier_id"), decision["message"]["action"]
        if sid not in threads or latest(threads[sid]).get("status") in ENDED:
            return False
        sheet_id, terms = standing(threads[sid])  # only the standing id: an `-a` id is not verified to be accepted
        if sheet_id is None or sheet_id != action.get("term_sheet_id"):
            return False
        std = standard_terms(threads[sid])
        if not must_haves_ok(case, terms, std):
            return False
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        return not alt.get("unit_price") or total_cost(case, terms, std) < total_cost(case, alt)

    def _fix(self, case, threads, sid, sheets):
        std = standard_terms(threads[sid]) if sid in threads else {}
        fixed, changes = fix_sheets(case, sheets, std)
        for c in changes:
            self.log.info("%s guard: fixed sheet (must-have): %s", self._case_id, c)
        return fixed

    def _last_move(self, case, threads, decision):
        """Rule e: on our last allowed message, a price push the supplier will refuse is replaced."""
        sid = decision["supplier_id"]
        if sid not in threads:
            return decision
        left = moves_left(case, threads[sid])
        if left > 1:
            return decision
        if left < 1:
            self.log.info("%s guard: closing move (no messages left on %s)", self._case_id, sid)
            return closing_move(case, threads)
        sheets = decision["message"].get("term_sheets") or []
        theirs = standing(threads[sid])[1].get("unit_price")
        prices = [p for p in (s["terms"].get("unit_price") for s in sheets) if p is not None]
        if theirs is None or not prices or min(prices) >= theirs:
            return decision
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "accept":
            self.log.info("%s guard: accept on last move (a lower counter would be refused)", self._case_id)
            return close
        self.log.info("%s guard: must-have counter at their price on last move", self._case_id)
        return self._counter(case, threads, sid)

    def _counter(self, case, threads, sid):
        events = threads[sid]
        _, terms = standing(events)
        if terms.get("unit_price") is None:
            body = _text(sid, ASK_QUOTE)
        else:
            sheet = satisfy_must_haves(case, dict(terms), standard_terms(events))
            body = _text(sid, ASK_BODY, [{"terms": sheet}])
        key = (self._case_id, sid)
        self._tried[key] = self._tried.get(key, 0) + 1
        return body

    def _eligible(self, case, threads, sid):
        events = threads[sid]
        status, left = latest(events).get("status"), moves_left(case, events)
        cap = 1 if status == "final_offer" else MAX_COUNTERS
        return status not in ENDED | {"agreed"} and left >= 1 and self._tried.get((self._case_id, sid), 0) < cap

    def _supplier_moved(self, case, threads, sid):
        """The standing sheet costs at most EARLY_ACCEPT x the thread's opening sheet."""
        events = threads[sid]
        std = standard_terms(events)
        _, terms = standing(events)
        opening = next((t for m in events if m.get("from") != "buyer"
                        for sh in m.get("term_sheets") or [] for t in [sh.get("terms") or {}]
                        if t.get("unit_price") is not None), None)
        if opening is None:
            return True
        return total_cost(case, terms, std) <= EARLY_ACCEPT * total_cost(case, opening, std)

    @staticmethod
    def _hopeless(case, threads):
        """Every live thread is at its final offer (or out of messages) and even its must-have-fixed sheet costs
        no less than the alternative: a counter could only end above the alternative's C."""
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        if not alt.get("unit_price"):
            return False
        c_alt = total_cost(case, alt)
        for sid in live_threads(threads):
            ev = threads[sid]
            if latest(ev).get("status") != "final_offer" and moves_left(case, ev) >= 1:
                return False
            terms = standing(ev)[1]
            if terms.get("unit_price") is not None:
                std = standard_terms(ev)
                if total_cost(case, satisfy_must_haves(case, dict(terms), std), std) < c_alt:
                    return False
        return True

    def _keep_going(self, case, threads, preferred, reason):
        """Rule d: never walk while something sensible is left."""
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "walk_away" and reason == "delegate wanted to walk" and self._hopeless(case, threads):
            self.log.info("%s guard: walk away stands (every thread is final, no counter beats the alternative)", self._case_id)
            return close
        if close["message"]["action"]["type"] == "accept":
            asid = close["supplier_id"]
            if (moves_left(case, threads[asid]) <= 1 or not self._eligible(case, threads, asid)
                    or self._supplier_moved(case, threads, asid)):
                self.log.info("%s guard: accept a safe standing sheet (%s)", self._case_id, reason)
                return close
        live = [s for s in live_threads(threads) if self._eligible(case, threads, s)]

        def cost(s):
            terms = standing(threads[s])[1]
            try:
                return total_cost(case, terms, standard_terms(threads[s])) if terms.get("unit_price") else float("inf")
            except Exception:
                return float("inf")

        order = ([preferred] if preferred in live else []) + sorted((s for s in live if s != preferred), key=cost)
        if not order:
            self.log.info("%s guard: closing move, no thread left to continue (%s)", self._case_id, reason)
            return close
        sid = order[0]
        self.log.info("%s guard: counter at their price on %s (%s)", self._case_id, sid, reason)
        return self._counter(case, threads, sid)
